func newClient(t *testing.T, port string) Client {
	client, err := NewClient(ToUint128(TIGERBEETLE_CLUSTER_ID), []string{port})
	if err != nil {
		t.Fatal(err)
	}

	return client
}

func u128(hex string) Uint128 {
	value, err := HexStringToUint128(hex)
	if err != nil {
		panic(err)
	}
	return value
}
